async function main() {
    const totalDays = await prisma.gameDay.count();
    const cancelled = await prisma.gameDay.count({ where: { game: false } });
    const played = await prisma.gameDay.count({ where: { game: true } });

    // Recent window: last 18 months, to see the "recent" trend the user mentioned
    const since = new Date();
    since.setMonth(since.getMonth() - 18);
    const recentTotal = await prisma.gameDay.count({
        where: { date: { gte: since } },
    });
    const recentCancelled = await prisma.gameDay.count({
        where: { date: { gte: since }, game: false },
    });

    // Prior window: 18-36 months ago, for comparison
    const priorSince = new Date();
    priorSince.setMonth(priorSince.getMonth() - 36);
    const priorTotal = await prisma.gameDay.count({
        where: { date: { gte: priorSince, lt: since } },
    });
    const priorCancelled = await prisma.gameDay.count({
        where: { date: { gte: priorSince, lt: since }, game: false },
    });

    // Current configured cost fields for recent played days
    const recentPlayedDays = await prisma.gameDay.findMany({
        where: { date: { gte: since }, game: true },
        select: { id: true, cost: true, hallCost: true, date: true },
        orderBy: { date: 'desc' },
    });

    // Average headcount charged per played game (PlayerGameCharge transactions)
    const chargeCounts = await prisma.transaction.groupBy({
        by: ['gameDayId'],
        where: {
            type: 'PlayerGameCharge',
            gameDay: { date: { gte: since } },
        },
        _count: { id: true },
    });
    const avgHeadcount =
        chargeCounts.length > 0
            ? chargeCounts.reduce((s, c) => s + c._count.id, 0) /
              chargeCounts.length
            : null;

    // Does a HallHire transaction get recorded for cancelled game days too?
    const cancelledDayIds = await prisma.gameDay.findMany({
        where: { date: { gte: since }, game: false },
        select: { id: true },
    });
    const cancelledIdList = cancelledDayIds.map((d) => d.id);
    const hallHireOnCancelled = cancelledIdList.length
        ? await prisma.transaction.count({
              where: {
                  type: 'HallHire',
                  gameDayId: { in: cancelledIdList },
              },
          })
        : 0;

    // Current cost/hallCost values in use (most recent few game days, played or not)
    const recentAny = await prisma.gameDay.findMany({
        select: { id: true, date: true, game: true, cost: true, hallCost: true },
        orderBy: { date: 'desc' },
        take: 15,
    });

    console.log(
        JSON.stringify(
            {
                totalDays,
                cancelled,
                played,
                recentTotal,
                recentCancelled,
                recentCancelledRate:
                    recentTotal > 0 ? recentCancelled / recentTotal : null,
                priorTotal,
                priorCancelled,
                priorCancelledRate:
                    priorTotal > 0 ? priorCancelled / priorTotal : null,
                avgHeadcountRecentPlayed: avgHeadcount,
